# In React, setting .value directly doesn't trigger React's synthetic onChange unless using nativeInputValueSetter
js("""
function setNativeValue(element, value) {
  const valueSetter = Object.getOwnPropertyDescriptor(element, 'value').set;
  const prototype = Object.getPrototypeOf(element);
  const prototypeValueSetter = Object.getOwnPropertyDescriptor(prototype, 'value').set;

  if (valueSetter && valueSetter !== prototypeValueSetter) {
    prototypeValueSetter.call(element, value);
  } else {
    valueSetter.call(element, value);
  }
}

const u = document.querySelector('#user-name');
setNativeValue(u, 'standard_user');
u.dispatchEvent(new Event('input', { bubbles: true }));

const p = document.querySelector('#password');
setNativeValue(p, 'secret_sauce');
p.dispatchEvent(new Event('input', { bubbles: true }));

document.querySelector('#login-button').click();
""")

